 // Monetary helpers.
 //
-// KNOWN DEFECT: amounts are accumulated in binary floating point, so sums drift
-// (0.1 + 0.2 !== 0.3) and half-cent rounding is unreliable.
+// Amounts are plain numbers in major units. Arithmetic is performed in integer
+// minor units (cents) only; binary floating point is touched once when crossing
+// the boundary, by `toCents`, which rounds a single time.
+
+/**
+ * Convert a plain amount in major units to integer cents.
+ *
+ * This is the one and only float -> cents boundary conversion. Rounding is
+ * half away from zero, applied to the magnitude so that negative amounts round
+ * symmetrically (-2.005 -> -2.01, not -2.00).
+ */
+function toCents(amount) {
+  return Math.sign(amount) * Math.round(Math.abs(amount) * 100);
+}
+
+/** Convert integer cents back to a plain amount in major units, once. */
+function fromCents(cents) {
+  return cents === 0 ? 0 : cents / 100;
+}

 /** Round a monetary amount to 2 decimal places. */
 export function roundMoney(amount) {
-  return Math.round(amount * 100) / 100;
+  return fromCents(toCents(amount));
 }

-/** Sum monetary amounts. */
+/** Sum monetary amounts without accumulating floating point drift. */
 export function sumAmounts(amounts) {
-  let total = 0;
+  let totalCents = 0;
   for (const amount of amounts) {
-    total += amount;
+    totalCents += toCents(amount);
   }
-  return total;
+  return fromCents(totalCents);
 }
